messages.text:
Pehle monthly totals banayein, phir window function lagayein:

WITH m AS (SELECT msisdn, date_trunc('month', recharge_date) AS mon, SUM(amount) AS amt FROM recharges GROUP BY 1,2)
SELECT msisdn, mon, AVG(amt) OVER (PARTITION BY msisdn ORDER BY mon ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS avg_3m FROM m;
